//! CSV dialect parity with `shape`. `tests/fixtures/shape/` holds shape's own CSV
//! fixtures plus edge files (sep= directive, a 64 KiB boundary inside a quoted record,
//! NULs inside and beyond the 8 KiB scan window, backslash escaping, BOM + sep=).
//! `shape.expected.json` records what shape's REAL input pipeline
//! (`shape::csv::input::parse_input_file`, shape 0.9.0 at 40587f3) did with each file,
//! once auto-detected and once with the delimiter forced to `,`. It was generated by
//! running shape's code, not by hand, so these tests compare this crate to shape.
//!
//! Known layering difference (the only one tolerated): shape's input layer reports a
//! header-only file as OK and decides `E_EMPTY` later; `open` reports `E_EMPTY` itself.

mod common;

use cmdrvl_tabular::{CsvOptions, OpenOptions, RefusalCode, open};
use common::*;
use serde_json::Value;

fn expected() -> Vec<Value> {
    serde_json::from_slice(&std::fs::read(fx("shape/shape.expected.json")).unwrap()).unwrap()
}

#[test]
fn every_shape_fixture_gets_shapes_outcome() {
    let entries = expected();
    assert!(entries.len() >= 40, "golden file looks truncated");
    let mut compared = 0;
    for entry in &entries {
        let file = entry["file"].as_str().unwrap();
        let forced = entry["forced_delimiter"].as_str().map(|s| s.as_bytes()[0]);
        let opts = OpenOptions {
            csv: CsvOptions {
                delimiter: forced,
                skip_rows: 0,
            },
            ..OpenOptions::default()
        };
        let want = &entry["shape"];
        let got = open(&fx(&format!("shape/{file}")), &opts);
        let label = format!("{file} (forced {forced:?})");
        match (want["outcome"].as_str().unwrap(), got) {
            ("ok", Ok(table)) => {
                let delimiter = want["delimiter"].as_str().unwrap().as_bytes()[0];
                assert_eq!(
                    table.source().delimiter,
                    Some(delimiter),
                    "{label} delimiter"
                );
                assert_eq!(
                    table.headers().len() as u64,
                    want["headers"].as_u64().unwrap(),
                    "{label} header count"
                );
            }
            ("ok", Err(refusal)) if refusal.code == RefusalCode::EEmpty => {
                // The tolerated layering difference: it must really be a header-only file.
                let text = std::fs::read_to_string(fx(&format!("shape/{file}"))).unwrap();
                assert!(
                    text.lines().count() <= 1,
                    "{label}: E_EMPTY on a file with rows"
                );
            }
            ("refused", Err(refusal)) => {
                assert_eq!(
                    refusal.code.as_str(),
                    want["code"].as_str().unwrap(),
                    "{label}: {refusal:?}"
                );
                if refusal.code == RefusalCode::EDialect {
                    assert_eq!(
                        refusal.context["candidates"], want["candidates"],
                        "{label} candidates"
                    );
                }
            }
            (expected_outcome, got) => {
                panic!("{label}: shape says {expected_outcome}, this crate got {got:?}")
            }
        }
        compared += 1;
    }
    assert_eq!(compared, entries.len());
}

#[test]
fn sep_directive_sets_the_delimiter_and_is_not_a_header() {
    let mut table = open(&fx("shape/edge_sep_semicolon.csv"), &OpenOptions::default()).unwrap();
    assert_eq!(table.source().delimiter, Some(b';'));
    let (headers, rows) = grid(&mut table);
    assert_eq!(headers, vec![b"loan_id".to_vec(), b"amount".to_vec()]);
    assert_eq!(rows, vec![vec![t("A1"), t("10")], vec![t("A2"), t("20")]]);
}

#[test]
fn nul_inside_the_8k_window_refuses_and_beyond_it_passes_like_shape() {
    let r = refusal("shape/edge_nul_before_8k.csv", &OpenOptions::default());
    assert_eq!(r.code, RefusalCode::EEncoding);
    let mut table = open(&fx("shape/edge_nul_after_8k.csv"), &OpenOptions::default()).unwrap();
    assert!(table.rows().all(|r| r.is_ok()));
}

#[test]
fn pinned_delimiter_falls_back_to_backslash_escaping_like_shape() {
    // Under RFC 4180 quoting the first data row has three fields (`x\` , `y"`...), which
    // does not match the two-field header, so the reader retries with backslash escaping,
    // where `"x\",y"` is one field. shape's golden above says OK for this file too.
    let opts = OpenOptions {
        csv: CsvOptions {
            delimiter: Some(b','),
            skip_rows: 0,
        },
        ..OpenOptions::default()
    };
    let mut table = open(&fx("shape/edge_backslash_needs_fallback.csv"), &opts).unwrap();
    let (_, rows) = grid(&mut table);
    assert_eq!(rows, vec![vec![t("1"), t("x\",y")], vec![t("2"), t("z")]]);
}
